(()=>{'use strict';let language='en';const list=document.getElementById('favorite-list'),error=document.getElementById('error'),tr=(en,zh)=>language==='zh'?zh:en;
 function failed(message){error.textContent=message;error.hidden=false;}
 async function action(id,operation){const result=await window.orbitFavorites.action(id,operation);if(!result?.ok)failed(result?.error||tr('Unable to complete this action.','操作未完成。'));else error.hidden=true;}
 function render(data){if(!data?.ok){failed(data?.error||tr('Unable to load favorites.','无法读取收藏。'));return;}language=data.language||'en';document.documentElement.lang=language==='zh'?'zh-CN':'en';document.title=tr('Favorites','收藏');document.getElementById('title').textContent=document.title;document.querySelector('.panel').setAttribute('aria-label',document.title);const close=document.getElementById('close');close.title=close.ariaLabel=tr('Close','关闭');list.replaceChildren();
  if(!data.items.length){const empty=document.createElement('div');empty.className='empty';empty.textContent=tr('No favorites yet. Select text or right-click an image to save it here.','暂无收藏。选中文字或右键点击图片，即可收藏到这里。');list.append(empty);return;}
  for(const item of data.items){const row=document.createElement('article');row.className='favorite-row';row.setAttribute('role','listitem');row.dataset.id=item.id;const content=document.createElement(item.kind==='image'?'div':'p');content.className='favorite-content';if(item.kind==='image'){const image=document.createElement('img');image.className='favorite-image';image.src=item.image;image.loading='lazy';image.alt=item.text||tr('Saved image','收藏的图片');image.addEventListener('error',()=>{image.hidden=true;content.textContent=tr('Saved image is unavailable.','收藏的图片不可用。');},{once:true});content.append(image);}else content.textContent=item.text;
   const source=document.createElement('a');source.className='favorite-source';source.href='#';source.textContent=item.title||item.sourceUrl||tr('Source page','来源网页');source.title=item.sourceUrl;source.addEventListener('click',event=>{event.preventDefault();action(item.id,'open');});
   const date=document.createElement('time');date.className='favorite-date';date.dateTime=item.createdAt;date.textContent=OrbitTime.format(item.createdAt,{dateStyle:'medium',timeStyle:'short'},data.timeZone||'America/Vancouver',language==='zh'?'zh-CN':'en-CA');
   const remove=document.createElement('button');remove.className='favorite-remove';remove.textContent='×';remove.title=remove.ariaLabel=tr('Remove from favorites','取消收藏');remove.addEventListener('click',()=>action(item.id,'remove'));row.append(content,remove,source,date);list.append(row);
  }
 }
 document.getElementById('close').onclick=()=>window.orbitFavorites.close();document.addEventListener('keydown',event=>{if(event.key==='Escape')window.orbitFavorites.close();});window.orbitFavorites.onChanged(render);window.orbitFavorites.get().then(render).catch(error=>failed(error.message));
})();
